callPartner(req, deadline):
    if breaker.isOpen():
        return fallback(req)

    if !bulkhead.tryAcquire():
        return degradeOrReject()

    try:
        return retryWithBackoff(
            maxAttempts = 2,
            onlyIdempotent = true,
            deadline = deadline,
            action = () -> partner.call(req)
        )
    catch e:
        breaker.recordFailure(e)
        return fallback(req)
    finally:
        bulkhead.release()
